import{_ as e,o as l,c as d,ao as o}from"./chunks/framework.CKOtou8s.js";const y=JSON.parse('{"title":"Control file reference","description":"","frontmatter":{},"headers":[],"relativePath":"developers/control_files.md","filePath":"developers/control_files.md","lastUpdated":null}'),a={name:"developers/control_files.md"};function r(i,t,s,n,c,f){return l(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="Control-file-reference" tabindex="-1">Control file reference <a class="header-anchor" href="#Control-file-reference" aria-label="Permalink to &quot;Control file reference {#Control-file-reference}&quot;">​</a></h1><p>Every key of every control file, with the settings of the mesh tools and of the 3D VFSA configuration. The user pages show only the keys that are changed most often.</p><h2 id="1D-inversion-InvCtrl.GN,-InvCtrl.VFSA" tabindex="-1">1D inversion (<code>InvCtrl.GN</code>, <code>InvCtrl.VFSA</code>) <a class="header-anchor" href="#1D-inversion-InvCtrl.GN,-InvCtrl.VFSA" aria-label="Permalink to &quot;1D inversion (`InvCtrl.GN`, `InvCtrl.VFSA`) {#1D-inversion-InvCtrl.GN,-InvCtrl.VFSA}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Key</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Algorithm</code></td><td style="text-align:left;"><code>GN</code> or <code>VFSA</code></td></tr><tr><td style="text-align:left;"><code>Mode</code></td><td style="text-align:left;">fitted impedance: <code>XY</code> (Zxy), <code>YX</code> (Zyx = −Z), <code>XYYX</code> (both) or <code>DET</code> (√det Z)</td></tr><tr><td style="text-align:left;"><code>Exit search when rms is less than</code></td><td style="text-align:left;">target rms</td></tr><tr><td style="text-align:left;"><code>Maximum number of iterations</code></td><td style="text-align:left;">iterations (per chain for VFSA)</td></tr><tr><td style="text-align:left;"><code>Initial damping factor lambda</code></td><td style="text-align:left;">GN only: regularisation weight</td></tr><tr><td style="text-align:left;"><code>Log10 resistivity bounds</code></td><td style="text-align:left;">VFSA only: the search box; GN is unbounded</td></tr><tr><td style="text-align:left;"><code>Number of chains</code></td><td style="text-align:left;">VFSA only: independent chains, and ensemble size</td></tr></tbody></table><p>Everything else is fixed in the code:</p><ul><li><p>GN: vertical smoothing with smallness 0.01, Levenberg–Marquardt damping 0.01, and a step of at most 0.5 in log10 ρ.</p></li><li><p>VFSA: every layer is a parameter (no sparse parameterisation), a fifth of them moved per proposal; temperature 0.03, cooling ratio 0.001, step scale 0.11. <code>model.rho</code> is the ensemble mean, and <code>vfsa/data.best.pred</code> holds the best chain&#39;s response.</p></li></ul><p>The 1D mesh settings (first layer δ(f_max)/5, growth 1.1, depth 4 δ(f_min)) are constants at the top of <code>examples/run_inv1D.jl</code>.</p><h2 id="2D-forward-fwd.ctrl" tabindex="-1">2D forward (<code>fwd.ctrl</code>) <a class="header-anchor" href="#2D-forward-fwd.ctrl" aria-label="Permalink to &quot;2D forward (`fwd.ctrl`) {#2D-forward-fwd.ctrl}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Key</th><th style="text-align:left;">Default</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Mode</code></td><td style="text-align:left;"><code>TETM</code></td><td style="text-align:left;"><code>TE</code>, <code>TM</code> or <code>TETM</code></td></tr><tr><td style="text-align:left;"><code>Strike (deg)</code></td><td style="text-align:left;"><code>auto</code></td><td style="text-align:left;"><code>auto</code> or degrees clockwise from north (see <a href="./solver2d">2D solver notes</a>)</td></tr><tr><td style="text-align:left;"><code>Air layers</code></td><td style="text-align:left;">10</td><td style="text-align:left;">number of air layers</td></tr><tr><td style="text-align:left;"><code>Air thickness (m)</code></td><td style="text-align:left;">50000</td><td style="text-align:left;">total air thickness</td></tr><tr><td style="text-align:left;"><code>Air growth factor</code></td><td style="text-align:left;">2</td><td style="text-align:left;">growth of the air layers upwards</td></tr><tr><td style="text-align:left;"><code>Air resistivity (ohm m)</code></td><td style="text-align:left;">1e9</td><td style="text-align:left;">resistivity given to all air cells, topographic air included</td></tr><tr><td style="text-align:left;"><code>Write Frechet derivative</code></td><td style="text-align:left;"><code>no</code></td><td style="text-align:left;"><code>yes</code> also writes G = ∂d/∂m as <code>data.frechet</code></td></tr><tr><td style="text-align:left;"><code>Dipole length (m)</code></td><td style="text-align:left;">100</td><td style="text-align:left;">TM electric dipole length, only used next to topographic steps</td></tr></tbody></table><p><code>fwd.ctrl</code> is required: it defines the air.</p><h2 id="2D-Gauss–Newton-and-NLCG-inv.ctrl" tabindex="-1">2D Gauss–Newton and NLCG (<code>inv.ctrl</code>) <a class="header-anchor" href="#2D-Gauss–Newton-and-NLCG-inv.ctrl" aria-label="Permalink to &quot;2D Gauss–Newton and NLCG (`inv.ctrl`) {#2D-Gauss–Newton-and-NLCG-inv.ctrl}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Key</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Algorithm</code></td><td style="text-align:left;"><code>GN</code> or <code>NLCG</code></td></tr><tr><td style="text-align:left;"><code>Initial damping factor lambda</code></td><td style="text-align:left;">β, the regularisation weight, fixed through the run</td></tr><tr><td style="text-align:left;"><code>Exit search when rms is less than</code></td><td style="text-align:left;">target rms</td></tr><tr><td style="text-align:left;"><code>Maximum number of iterations</code></td><td style="text-align:left;">iteration cap</td></tr><tr><td style="text-align:left;"><code>Mode</code></td><td style="text-align:left;"><code>TE</code>, <code>TM</code> or <code>TETM</code></td></tr><tr><td style="text-align:left;"><code>Max log10 step</code></td><td style="text-align:left;">largest change of any cell in one step, in log10 ρ</td></tr><tr><td style="text-align:left;"><code>Max line search steps</code></td><td style="text-align:left;">backtracking steps before a step is rejected</td></tr><tr><td style="text-align:left;"><code>Smallness weight</code></td><td style="text-align:left;">weight of the smallness term in the regulariser</td></tr><tr><td style="text-align:left;"><code>Smoothing weight y</code>, <code>Smoothing weight z</code></td><td style="text-align:left;">weights of the horizontal and vertical first differences</td></tr><tr><td style="text-align:left;"><code>GN damping</code></td><td style="text-align:left;">GN only: initial Levenberg–Marquardt λ</td></tr><tr><td style="text-align:left;"><code>NLCG restart</code></td><td style="text-align:left;">NLCG only: restart to steepest descent every N iterations</td></tr><tr><td style="text-align:left;"><code>NLCG precondition</code></td><td style="text-align:left;">NLCG only: <code>yes</code> uses the regulariser as preconditioner</td></tr></tbody></table><p>GN and NLCG are unbounded: <code>Log10 resistivity bounds</code> belongs to VFSA and is an error in <code>inv.ctrl</code>.</p><h2 id="2D-VFSA-vfsa.ctrl" tabindex="-1">2D VFSA (<code>vfsa.ctrl</code>) <a class="header-anchor" href="#2D-VFSA-vfsa.ctrl" aria-label="Permalink to &quot;2D VFSA (`vfsa.ctrl`) {#2D-VFSA-vfsa.ctrl}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Key</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Maximum number of iterations</code></td><td style="text-align:left;">iterations per chain</td></tr><tr><td style="text-align:left;"><code>Exit search when rms is less than</code></td><td style="text-align:left;">a chain stops once its best rms reaches it</td></tr><tr><td style="text-align:left;"><code>Mode</code></td><td style="text-align:left;"><code>TE</code>, <code>TM</code> or <code>TETM</code></td></tr><tr><td style="text-align:left;"><code>Log10 resistivity bounds</code></td><td style="text-align:left;">the search box</td></tr><tr><td style="text-align:left;"><code>Number of chains</code></td><td style="text-align:left;">independent chains (and ensemble size)</td></tr><tr><td style="text-align:left;"><code>Control points</code></td><td style="text-align:left;">RBF controls per chain, drawn among the free core cells</td></tr><tr><td style="text-align:left;"><code>Trials per iteration</code></td><td style="text-align:left;">proposals per iteration; the best takes one Metropolis test</td></tr><tr><td style="text-align:left;"><code>Share of controls moved</code></td><td style="text-align:left;">controls perturbed per proposal (3D <code>frac_update_controls</code>)</td></tr><tr><td style="text-align:left;"><code>Step scale</code></td><td style="text-align:left;">proposal width as a share of the box</td></tr><tr><td style="text-align:left;"><code>Starting temperature</code>, <code>Cooling ratio</code></td><td style="text-align:left;">start temperature, on the scale of a typical relative uphill change of rms², and its ratio at the last iteration</td></tr><tr><td style="text-align:left;"><code>RBF width top (cells)</code>, <code>RBF width bottom (cells)</code></td><td style="text-align:left;">kernel widths at the top and bottom of the core, linear in depth between (3D <code>sigma_scale</code>, <code>sigma_scale_deep</code>)</td></tr><tr><td style="text-align:left;"><code>Control depth power</code></td><td style="text-align:left;">control placement weight (depth + z₁)^(−p), 0 = uniform (3D <code>ctrl_depth_power</code>)</td></tr><tr><td style="text-align:left;"><code>Core depth (skin depths)</code></td><td style="text-align:left;">core depth in skin depths of the data: median off-diagonal ρa, longest period</td></tr><tr><td style="text-align:left;"><code>Core depth (layers)</code></td><td style="text-align:left;">core depth as the top N layers instead, when N &gt; 0</td></tr><tr><td style="text-align:left;"><code>Core expansion (cells)</code></td><td style="text-align:left;">cells added to each side of the uniform lateral core (3D <code>core_expand_cells</code>)</td></tr><tr><td style="text-align:left;"><code>Padding decay (core cells)</code></td><td style="text-align:left;">e-fold of the blend from the core edge back to the start model</td></tr><tr><td style="text-align:left;"><code>Random seed</code></td><td style="text-align:left;">chain k uses seed + 1000(k−1)</td></tr><tr><td style="text-align:left;"><code>Snapshot interval</code></td><td style="text-align:left;">write each chain&#39;s best model every N iterations (0 = off)</td></tr></tbody></table><p><code>ReadVFSACtrl2D</code> and <code>WriteVFSACtrl2D</code> read and write the file, and <code>VFSA2DConfig(ctrl)</code> turns it into the in-memory configuration.</p><h2 id="mask.ctrl" tabindex="-1"><code>mask.ctrl</code> <a class="header-anchor" href="#mask.ctrl" aria-label="Permalink to &quot;`mask.ctrl` {#mask.ctrl}&quot;">​</a></h2><p>Our own format: a first line <code>ny nz</code>, then <code>nz</code> rows of <code>ny</code> integers, top row first. The values are those of the covariance mask: 0 = air or fixed, 9 = water, others free. <code>cov.ctrl</code> keeps the ModEM covariance layout, but only its mask is read.</p><h2 id="MakeMesh2D" tabindex="-1"><code>MakeMesh2D</code> <a class="header-anchor" href="#MakeMesh2D" aria-label="Permalink to &quot;`MakeMesh2D` {#MakeMesh2D}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Setting</th><th style="text-align:left;">Default</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>cell_width_frac</code></td><td style="text-align:left;">0.5</td><td style="text-align:left;">core cell width as a fraction of the median station spacing</td></tr><tr><td style="text-align:left;"><code>core_margin_cells</code></td><td style="text-align:left;">4</td><td style="text-align:left;">core cells beyond the outer stations</td></tr><tr><td style="text-align:left;"><code>n_pad</code>, <code>pad_factor</code></td><td style="text-align:left;">12, 1.3</td><td style="text-align:left;">lateral padding cells each side and their growth</td></tr><tr><td style="text-align:left;"><code>first_layer_div</code></td><td style="text-align:left;">5</td><td style="text-align:left;">first layer = δ(f_max) / this</td></tr><tr><td style="text-align:left;"><code>vertical_factor</code></td><td style="text-align:left;">1.1</td><td style="text-align:left;">layer growth with depth</td></tr><tr><td style="text-align:left;"><code>depth_mult</code></td><td style="text-align:left;">4</td><td style="text-align:left;">model depth = this × δ(f_min)</td></tr><tr><td style="text-align:left;"><code>background_resistivity</code></td><td style="text-align:left;">0</td><td style="text-align:left;">0 = median apparent resistivity of the data</td></tr><tr><td style="text-align:left;"><code>air_layers</code>, <code>air_thickness</code>, <code>air_growth</code>, <code>air_resistivity</code></td><td style="text-align:left;">10, 50 km, 2, 1e9</td><td style="text-align:left;">the air in <code>fwd.ctrl</code></td></tr><tr><td style="text-align:left;"><code>dipole_length</code></td><td style="text-align:left;">100</td><td style="text-align:left;">TM dipole averaging next to topographic steps</td></tr><tr><td style="text-align:left;"><code>cov_smoothing</code>, <code>n_smooth</code></td><td style="text-align:left;">0.3, 1</td><td style="text-align:left;">smoothing values kept in the ModEM covariance layout</td></tr><tr><td style="text-align:left;"><code>fixed_below_m</code></td><td style="text-align:left;">Inf</td><td style="text-align:left;">fix cells below this depth (mask 0)</td></tr><tr><td style="text-align:left;"><code>water_resistivity</code></td><td style="text-align:left;">100</td><td style="text-align:left;">lakes and sea</td></tr><tr><td style="text-align:left;"><code>strike</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;"><code>nothing</code> = auto from the data, or degrees clockwise from north; written to <code>fwd.ctrl</code></td></tr><tr><td style="text-align:left;"><code>inv_ctrl</code></td><td style="text-align:left;"><code>examples/ctrl/2D/InvCtrl.GN</code></td><td style="text-align:left;">copied as <code>inv.ctrl</code></td></tr><tr><td style="text-align:left;"><code>vfsa_ctrl</code></td><td style="text-align:left;"><code>examples/ctrl/2D/InvCtrl.VFSA</code></td><td style="text-align:left;">copied as <code>vfsa.ctrl</code></td></tr></tbody></table><p>The core is centred on y = 0 (the data&#39;s origin), as ModEM expects.</p><h2 id="VFSA3DMTConfig" tabindex="-1"><code>VFSA3DMTConfig</code> <a class="header-anchor" href="#VFSA3DMTConfig" aria-label="Permalink to &quot;`VFSA3DMTConfig` {#VFSA3DMTConfig}&quot;">​</a></h2><p>Fields without a default must be given; <code>examples/run_vfsa3D.jl</code> sets all of them.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Default</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>nprocs</code></td><td style="text-align:left;"></td><td style="text-align:left;">MPI processes for each ModEM forward call</td></tr><tr><td style="text-align:left;"><code>mpirun_cmd</code></td><td style="text-align:left;"></td><td style="text-align:left;">MPI launcher, e.g. <code>&quot;mpirun&quot;</code> or <code>&quot;srun&quot;</code></td></tr><tr><td style="text-align:left;"><code>modem_exe</code></td><td style="text-align:left;"></td><td style="text-align:left;">ModEM executable</td></tr><tr><td style="text-align:left;"><code>fwd_ctrl</code></td><td style="text-align:left;"><code>&quot;&quot;</code></td><td style="text-align:left;">ModEM forward control file; <code>&quot;&quot;</code> uses the binary&#39;s compiled-in solver defaults</td></tr><tr><td style="text-align:left;"><code>out_root</code></td><td style="text-align:left;"></td><td style="text-align:left;">run folder base name; <code>_&lt;timestamp&gt;</code> is appended, relative paths sit next to the start model</td></tr><tr><td style="text-align:left;"><code>n_ctrl</code></td><td style="text-align:left;"></td><td style="text-align:left;">Gaussian RBF control points in the core</td></tr><tr><td style="text-align:left;"><code>frac_update_controls</code></td><td style="text-align:left;"></td><td style="text-align:left;">share of controls perturbed per trial</td></tr><tr><td style="text-align:left;"><code>log_bounds</code></td><td style="text-align:left;"></td><td style="text-align:left;">search box in log10 Ω·m</td></tr><tr><td style="text-align:left;"><code>step_scale</code></td><td style="text-align:left;"></td><td style="text-align:left;">largest control jump, as a share of the box width</td></tr><tr><td style="text-align:left;"><code>max_iter</code></td><td style="text-align:left;"></td><td style="text-align:left;">iteration cap; also sets the cooling timescale</td></tr><tr><td style="text-align:left;"><code>n_trials</code></td><td style="text-align:left;"></td><td style="text-align:left;">trials per iteration; the best takes one Metropolis test (1 = classic VFSA)</td></tr><tr><td style="text-align:left;"><code>T0</code>, <code>cool_ratio</code></td><td style="text-align:left;"></td><td style="text-align:left;">start temperature, and the final temperature as a share of it</td></tr><tr><td style="text-align:left;"><code>target_rms</code></td><td style="text-align:left;"></td><td style="text-align:left;">early-stop rms</td></tr><tr><td style="text-align:left;"><code>seed</code></td><td style="text-align:left;"></td><td style="text-align:left;">random seed</td></tr><tr><td style="text-align:left;"><code>pad_tol</code></td><td style="text-align:left;"></td><td style="text-align:left;">tolerance of the core/padding detection</td></tr><tr><td style="text-align:left;"><code>core_expand_cells</code></td><td style="text-align:left;">0</td><td style="text-align:left;">grow the lateral core by N cells per side</td></tr><tr><td style="text-align:left;"><code>padding_decay_length</code></td><td style="text-align:left;"></td><td style="text-align:left;">lateral padding blend e-fold, in core cells</td></tr><tr><td style="text-align:left;"><code>z_core_skin_depths</code></td><td style="text-align:left;">1.0</td><td style="text-align:left;">core depth in data skin depths (<code>Inf</code> = full column)</td></tr><tr><td style="text-align:left;"><code>z_core_cells</code></td><td style="text-align:left;">0</td><td style="text-align:left;">core depth as the top N layers instead, when N &gt; 0</td></tr><tr><td style="text-align:left;"><code>keep_models</code>, <code>keep_dpred</code></td><td style="text-align:left;"></td><td style="text-align:left;">keep every trial model and predicted data file</td></tr><tr><td style="text-align:left;"><code>model_save_every</code></td><td style="text-align:left;"></td><td style="text-align:left;">&gt; 0 keeps the winning trial model every N iterations</td></tr><tr><td style="text-align:left;"><code>sigma_scale</code>, <code>sigma_scale_deep</code></td><td style="text-align:left;"></td><td style="text-align:left;">RBF 1σ in cells at the top and bottom of the core</td></tr><tr><td style="text-align:left;"><code>trunc_sigmas</code></td><td style="text-align:left;"></td><td style="text-align:left;">RBF kernels are cut beyond this many σ</td></tr><tr><td style="text-align:left;"><code>ctrl_depth_power</code></td><td style="text-align:left;"></td><td style="text-align:left;">control placement weight (depth + z₁)^(−p)</td></tr><tr><td style="text-align:left;"><code>water_log10</code></td><td style="text-align:left;"></td><td style="text-align:left;">start-model cells below this log10 ρ are frozen water (<code>NaN</code> = off)</td></tr><tr><td style="text-align:left;"><code>bathymetry_file</code></td><td style="text-align:left;"></td><td style="text-align:left;">frozen water from a bathymetry file instead (<code>&quot;&quot;</code> = off)</td></tr><tr><td style="text-align:left;"><code>distortion_mode</code></td><td style="text-align:left;"><code>:off</code></td><td style="text-align:left;"><code>:on</code> fits a per-site 2 × 2 galvanic distortion matrix at every misfit evaluation</td></tr><tr><td style="text-align:left;"><code>distortion_damping</code></td><td style="text-align:left;">0.01</td><td style="text-align:left;">pull of that matrix towards the identity; <code>Inf</code> = correction off</td></tr></tbody></table>',24)])])}const x=e(a,[["render",r]]);export{y as __pageData,x as default};
